optimized-checkout.scss:
// =============================================================================
// Stencil Checkout - Customize the Optimized Single-Page Checkout experience
// =============================================================================

// =============================================================================
//
// IMPORTANT DISCLAIMER
// Please do not nest elements within class selectors, and do not use class selectors other than those given below.
// Future support is guaranteed only if class selectors' structure and naming are left unchanged.
//
// =============================================================================

//
// Header Section
// Background, Logo Position
// -----------------------------------------------------------------------------

*:focus {
    outline-color: stencilColor("optimizedCheckout-colorFocus");
}

.optimizedCheckout-header {
    background-color: stencilColor("optimizedCheckout-header-backgroundColor");
    /* stylelint-disable function-url-quotes*/
    background-image: url(stencilImage('optimizedCheckout-backgroundImage', 'optimizedCheckout-backgroundImage-size'));
    /* stylelint-enable */
    background-size: cover;
    border-color: stencilColor("optimizedCheckout-header-borderColor");
    color: stencilColor("optimizedCheckout-header-textColor");

    //
    // TODO:
    // Configure media query to be 'desktop' breakpoint size
    // -----------------------------------------------------------------------------
    @media (min-width: 801px) {
        text-align: stencilString("optimizedCheckout-logo-position");
    }
}

//
// Primary and Secondary Headings
// Text Color & Typography
// .optimizedCheckout-headingPrimary styles top-level headings.
// .optimizedCheckout-headingSecondary styles certain lower-level elements, such as descriptions of cart items.
// -----------------------------------------------------------------------------

.optimizedCheckout-headingPrimary {
    color: stencilColor("optimizedCheckout-headingPrimary-color");
    font-family: stencilFontFamily("optimizedCheckout-headingPrimary-font"), Arial, Helvetica, sans-serif;
    font-weight: stencilFontWeight("optimizedCheckout-headingPrimary-font");
}

.optimizedCheckout-headingSecondary {
    color: stencilColor("optimizedCheckout-headingSecondary-color");
    font-family: stencilFontFamily("optimizedCheckout-headingSecondary-font"), Arial, Helvetica, sans-serif;
    font-weight: stencilFontWeight("optimizedCheckout-headingSecondary-font");
}

//
// Body
// Background & Shipping Method Overlay
// -----------------------------------------------------------------------------

body {
    background-color: stencilColor("optimizedCheckout-body-backgroundColor");
}

.optimizedCheckout-overlay {
    background-color: stencilColor("optimizedCheckout-body-backgroundColor");
    border-color: stencilColor("optimizedCheckout-step-borderColor");
    color: stencilColor("optimizedCheckout-contentPrimary-color");
}

//
// Primary & Secondary Content
// Text Color & Typography
// .optimizedCheckout-contentPrimary styles body text in the Order Summary/Order Confirmation; drop-down-list items; and text that summarizes completed steps.
// .optimizedCheckout-contentSecondary styles check boxes' text labels, and lower-level text in the Order Summary.
// -----------------------------------------------------------------------------

.optimizedCheckout-contentPrimary {
    color: stencilColor("optimizedCheckout-contentPrimary-color");
    font-family: stencilFontFamily("optimizedCheckout-contentPrimary-font"), Arial, Helvetica, sans-serif;
    font-weight: stencilFontWeight("optimizedCheckout-contentPrimary-font");
}

.optimizedCheckout-contentSecondary {
    color: stencilColor("optimizedCheckout-contentSecondary-color");
    font-family: stencilFontFamily("optimizedCheckout-contentSecondary-font"), Arial, Helvetica, sans-serif;
    font-weight: stencilFontWeight("optimizedCheckout-contentSecondary-font");
}

//
// Primary Button
// Background & Border & Text Color & Typography
// Styles the CONTINUE button for each step, & the final confirmation button.
// -----------------------------------------------------------------------------

.optimizedCheckout-buttonPrimary {
    background-color: stencilColor("optimizedCheckout-buttonPrimary-backgroundColor");
    border-color: stencilColor("optimizedCheckout-buttonPrimary-borderColor");
    color: stencilColor("optimizedCheckout-buttonPrimary-color");
    font-family: stencilFontFamily("optimizedCheckout-buttonPrimary-font"), Arial, Helvetica, sans-serif;
    font-weight: stencilFontWeight("optimizedCheckout-buttonPrimary-font");

    &:focus,
    &:hover {
        background-color: stencilColor("optimizedCheckout-buttonPrimary-backgroundColorHover");
        border-color: stencilColor("optimizedCheckout-buttonPrimary-borderColorHover");
        color: stencilColor("optimizedCheckout-buttonPrimary-colorHover");
    }

    &:focus {
        border-color: stencilColor("optimizedCheckout-colorFocus");
        box-shadow: 0 0 3px stencilColor("optimizedCheckout-colorFocus");
    }

    &:active {
        background-color: stencilColor("optimizedCheckout-buttonPrimary-backgroundColorActive");
        border-color: stencilColor("optimizedCheckout-buttonPrimary-borderColorActive");
        color: stencilColor("optimizedCheckout-buttonPrimary-colorActive");
    }

    &[disabled],
    &[disabled]:hover,
    &[disabled]:focus,
    &[disabled].is-active,
    &[disabled].is-loading,
    &[disabled].active {
        background-color: stencilColor("optimizedCheckout-buttonPrimary-backgroundColorDisabled");
        border-color: stencilColor("optimizedCheckout-buttonPrimary-borderColorDisabled");
        color: stencilColor("optimizedCheckout-buttonPrimary-colorDisabled");
    }
}

//
// Secondary Button
// Background & Border & Text Color & Typography
// Styles the EDIT button for each step.
// -----------------------------------------------------------------------------

.optimizedCheckout-buttonSecondary {
    background-color: stencilColor("optimizedCheckout-buttonSecondary-backgroundColor");
    border-color: stencilColor("optimizedCheckout-buttonSecondary-borderColor");
    color: stencilColor("optimizedCheckout-buttonSecondary-color");
    font-family: stencilFontFamily("optimizedCheckout-buttonSecondary-font"), Arial, Helvetica, sans-serif;
    font-weight: stencilFontWeight("optimizedCheckout-buttonSecondary-font");

    &:focus,
    &:hover {
        background-color: stencilColor("optimizedCheckout-buttonSecondary-backgroundColorHover");
        border-color: stencilColor("optimizedCheckout-buttonSecondary-borderColorHover");
        color: stencilColor("optimizedCheckout-buttonSecondary-colorHover");
    }

    &:focus {
        border-color: stencilColor("optimizedCheckout-colorFocus");
        box-shadow: 0 0 3px stencilColor("optimizedCheckout-colorFocus");
    }

    &:active {
        background-color: stencilColor("optimizedCheckout-buttonSecondary-backgroundColorActive");
        border-color: stencilColor("optimizedCheckout-buttonSecondary-borderColorActive");
        color: stencilColor("optimizedCheckout-buttonSecondary-colorActive");
    }

    &[disabled],
    &[disabled]:hover,
    &[disabled]:focus,
    &[disabled].is-active,
    &[disabled].is-loading,
    &[disabled].active {
        background-color: stencilColor("optimizedCheckout-buttonPrimary-backgroundColorDisabled");
        border-color: stencilColor("optimizedCheckout-buttonPrimary-borderColorDisabled");
        color: stencilColor("optimizedCheckout-buttonPrimary-colorDisabled");
    }
}

//
// Links
// Text Color & Typography
// -----------------------------------------------------------------------------

a {
    color: stencilColor("optimizedCheckout-link-color");
    font-family: stencilFontFamily("optimizedCheckout-link-font"), Arial, Helvetica, sans-serif;
    font-weight: stencilFontWeight("optimizedCheckout-link-font");

    &:focus,
    &:hover {
        color: stencilColor("optimizedCheckout-link-hoverColor");
    }
}

//
// Order Summary (Mobile Drawer & Modal)
// Background Color
// -----------------------------------------------------------------------------

.optimizedCheckout-orderSummary {
    background-color: stencilColor("optimizedCheckout-orderSummary-backgroundColor");
    border-color: stencilColor("optimizedCheckout-orderSummary-borderColor");
    box-shadow: 0 4px 8px transparentize(stencilColor("optimizedCheckout-orderSummary-borderColor"), 0.5);
}

.optimizedCheckout-orderSummary-cartSection {
    border-color: stencilColor("optimizedCheckout-orderSummary-borderColor");
}

.optimizedCheckout-checkoutStep {
    border-color: stencilColor("optimizedCheckout-step-borderColor");
}

//
// Checkout Steps
// Background & Text Color
// Styles the large step-number indicators on the page's left side.
// -----------------------------------------------------------------------------

.optimizedCheckout-step {
    background-color: stencilColor("optimizedCheckout-step-backgroundColor");

    &::before {
        color: stencilColor("optimizedCheckout-step-textColor");
    }

    svg {
        fill: stencilColor("optimizedCheckout-step-textColor");
    }
}

//
// Form Labels
// Text Color
// Styles text labels on form fields.
// -----------------------------------------------------------------------------

.optimizedCheckout-form-label {
    color: stencilColor("optimizedCheckout-form-textColor");
}

.form-field--error {
    .optimizedCheckout-form-label,
    .form-inlineMessage {
        color: stencilColor("optimizedCheckout-formField-errorColor");
    }
}
//
// Form Input
// Background, Border, Shadow and Text Color
// Styles form fields.
// -----------------------------------------------------------------------------

$optimizedCheckout-input-boxShadow: inset 0 1px 1px stencilColor("optimizedCheckout-formField-shadowColor");
$optimizedCheckout-input--focus-boxShadow: 0 0 3px transparentize(stencilColor("optimizedCheckout-colorFocus"), 0.4);
$optimizedCheckout-input--error-boxShadow: 0 0 3px transparentize(stencilColor("optimizedCheckout-formField-errorColor"), 0.4);

.optimizedCheckout-form-input,
.optimizedCheckout-form-select {
    background-color: stencilColor("optimizedCheckout-formField-backgroundColor");
    border-color: stencilColor("optimizedCheckout-formField-borderColor");
    box-shadow: $optimizedCheckout-input-boxShadow;
    color: stencilColor("optimizedCheckout-formField-textColor");

    &::placeholder {
        color: stencilColor("optimizedCheckout-formField-placeholderColor");
    }

    .form-field--error & {
        background-color: stencilColor("optimizedCheckout-formField-backgroundColor");
        border-color: stencilColor("optimizedCheckout-formField-errorColor");
        box-shadow: $optimizedCheckout-input--error-boxShadow, $optimizedCheckout-input-boxShadow;
    }
}

.optimizedCheckout-form-input:focus,
.optimizedCheckout-form-select:focus,
.optimizedCheckout-form-select:hover {
    background-color: stencilColor("optimizedCheckout-formField-backgroundColor");
    border-color: stencilColor("optimizedCheckout-colorFocus");
    box-shadow: $optimizedCheckout-input--focus-boxShadow, $optimizedCheckout-input-boxShadow;
}

.optimizedCheckout-form-label::before {
    .optimizedCheckout-form-radio + &,
    .optimizedCheckout-form-checkbox + & {
        background-color: stencilColor("optimizedCheckout-formField-backgroundColor");
        border-color: stencilColor("optimizedCheckout-formField-borderColor");
        box-shadow: $optimizedCheckout-input-boxShadow;
        opacity: 1;
    }

    .optimizedCheckout-form-radio:checked + &,
    .optimizedCheckout-form-checkbox:checked + & {
        background-color: stencilColor("optimizedCheckout-formField-inputControlColor");
        border-color: stencilColor("optimizedCheckout-formField-inputControlColor");
        box-shadow: none;
    }

    .optimizedCheckout-form-radio:focus + &,
    .optimizedCheckout-form-checkbox:focus + & {
        border-color: stencilColor("optimizedCheckout-colorFocus");
        box-shadow: $optimizedCheckout-input--focus-boxShadow, $optimizedCheckout-input-boxShadow;
    }

    .optimizedCheckout-form-radio:focus:checked + &,
    .optimizedCheckout-form-checkbox:focus:checked + & {
        box-shadow: $optimizedCheckout-input--focus-boxShadow;
    }
}

//
// Discount Banners
// Background & Text & Icon Color
// Styles discount banners.
// -----------------------------------------------------------------------------

.optimizedCheckout-discountBanner {
    background-color: stencilColor("optimizedCheckout-discountBanner-backgroundColor");
    color: stencilColor("optimizedCheckout-discountBanner-textColor");
    font-family: stencilFontFamily("optimizedCheckout-link-font"), Arial, Helvetica, sans-serif;
    font-weight: stencilFontWeight("optimizedCheckout-link-font");

    svg {
        fill: stencilColor("optimizedCheckout-discountBanner-iconColor");
    }
}

//
// Form Checklist (Shipping / Payment methods)
// Background & Border & Text Color
// Styles form checklists
// -----------------------------------------------------------------------------

.optimizedCheckout-form-checklist {
    background-color: stencilColor("optimizedCheckout-formChecklist-backgroundColor");
    border-color: stencilColor("optimizedCheckout-formChecklist-borderColor");
    color: stencilColor("optimizedCheckout-formChecklist-color");
}

.optimizedCheckout-form-checklist-item {
    background-color: stencilColor("optimizedCheckout-formChecklist-backgroundColor");
    border-color: stencilColor("optimizedCheckout-formChecklist-borderColor");
}

.optimizedCheckout-form-checklist-item:hover,
.optimizedCheckout-form-checklist-item--selected {
    background-color: stencilColor("optimizedCheckout-formChecklist-backgroundColorSelected");
    border-color: stencilColor("optimizedCheckout-formChecklist-borderColor");
}

.optimizedCheckout-form-checklist-checkbox {
    ~ .form-label::after,
    ~ .form-label::before {
        background-color: stencilColor("optimizedCheckout-formField-backgroundColor");
        border-color: stencilColor("optimizedCheckout-formField-borderColor");
    }

    &:focus ~ .form-label {
        box-shadow: inset 0 0 0 1px stencilColor("optimizedCheckout-colorFocus");
    }

    &:checked ~ .form-label::before {
        border-color: stencilColor("optimizedCheckout-formField-inputControlColor");
    }

    &:checked ~ .form-label::after {
        background: stencilColor("optimizedCheckout-formField-inputControlColor");
    }
}

//
// Loading Toaster
// Background & Text Color
// Styles the Loading Toaster
// -----------------------------------------------------------------------------

.optimizedCheckout-loadingToaster {
    background-color: stencilColor("optimizedCheckout-loadingToaster-backgroundColor");
    color: stencilColor("optimizedCheckout-loadingToaster-textColor");
}


//
// obundle
// Austin Theme Customizations
// -----------------------------------------------------------------------------
@import 'settings/global/screensizes/_screensizes';
@import 'ob-custom/ob-checkout';

ob-custom/ob-checkout.scss:
//***************************
// VARIABLES
//***************************

$form-spacing:                      spacing("single");
$input-horizontalPadding:           ($form-spacing / 1.5);
$input-verticalPadding:             ($form-spacing / 2);
$select-arrow-color:                rgba(stencilColor("select-arrow-color"), 0.999);
$select-padding:                    $input-verticalPadding (spacing("double")) $input-verticalPadding $input-horizontalPadding;
$select-backgroundImage:            url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='24' height='24' viewBox='0 0 24 24'%3E%3Cpath d='M16.59 8.59L12 13.17 7.41 8.59 6 10l6 6 6-6z' fill='#{$select-arrow-color}' /%3E%3C/svg%3E");
$select-backgroundPosition:         right (spacing("quarter") + spacing("eighth")) top spacing("third") + spacing("eighth");

$screen-xlarge:                 1441px;
$screen-large:                  1261px;
$screen-medium:                 801px;
$screen-small:                  551px;

@import "framework/ob-variables";
@import "global/ob-buttons";
@import "global/ob-forms";

//***************************
//Headings
//***************************
.ob-vogue-checkout {
    h1, h2, h3, h4 {
        font-weight: bold;
        line-height: 110%;
        letter-spacing: 1.2px;
    }
}

//***************************
//Button Styling
//***************************
.stepHeader-actions.stepHeader-column button,
#checkout-customer-continue {
    height: 45px;
    padding: 0 15px;
}

// LIGHT VARIANT
.ob-light-checkout {
    .stepHeader-actions.stepHeader-column button {
        background: stencilColor("button_bordered_background")!important;
        border: 4px solid stencilColor("button_bordered_border");
        color: stencilColor("button_bordered_text")!important;

        &:hover {
          background: stencilColor("button_bordered_background_hover")!important;
          border-color: stencilColor("button_bordered_border_hover");
          color: stencilColor("button_bordered_text_hover")!important;
          box-shadow: 0px 7px 28px -12px stencilColor("button_bordered_border");

          svg {
            stroke: stencilColor("button_bordered_text_hover");
            fill: stencilColor("button_bordered_text_hover");
          }
        }
    }
}

// NIGHT VARIANT
.ob-night-checkout {
    .stepHeader-actions.stepHeader-column button {
        background: stencilColor("button_bordered_background")!important;
        border: 4px solid stencilColor("button_bordered_border");
        color: stencilColor("button_bordered_text")!important;

        &:hover {
          background: stencilColor("button_bordered_background_hover")!important;
          border-color: stencilColor("button_bordered_border_hover");
          color: stencilColor("button_bordered_text_hover")!important;
          box-shadow: 0px 7px 28px -12px stencilColor("button_bordered_border");

          svg {
            stroke: stencilColor("button_bordered_text_hover");
            fill: stencilColor("button_bordered_text_hover");
          }
        }
    }
}

// VOGUE VARIANT
.ob-vogue-checkout {
    .stepHeader-actions.stepHeader-column button {
        background: stencilColor("button_bordered_background")!important;
        border: 2px solid stencilColor("button_bordered_border");
        color: stencilColor("button_bordered_text")!important;

        &:hover {
          background: stencilColor("button_bordered_background_hover")!important;
          border-color: stencilColor("button_bordered_border_hover");
          color: stencilColor("button_bordered_text_hover")!important;
          box-shadow: 0px 7px 28px -12px stencilColor("button_bordered_border");

          svg {
            stroke: stencilColor("button_bordered_text_hover");
            fill: stencilColor("button_bordered_text_hover");
          }
        }
    }
}


//***************************
// Consent Manager
//***************************
[data-consent-manager-dialog] {
  div {
    color: $ob-text-primary;
  }

  h1, h2, h3, h4, h5 {
    color: $ob-text-primary;
  }
  button[title="Cancel"] {
    height: 40px;
    padding: 0;
  }

  [role="dialog"] {
    background: stencilColor("body-bg");
  }

  th {
    background: stencilColor("content_inner_panel_bg");
    color: $ob-text-primary!important;
  }

  label,
  td {
    color: $ob-text-primary!important;
  }

  input[type="radio"] {
    accent-color: stencilColor("color-activeForms");
  }

  button {
    color: $ob-text-primary;
    letter-spacing: 0.025em;
    &+ button {
      background: stencilColor("content_inner_panel_secondary_bg");
    }
  }
}
#consent-manager-update-banner,
#consent-manager > div > div {
  background: stencilColor("content_inner_panel_secondary_bg")!important;
  color: stencilColor("color-textBase")!important;
  a {
    color: inherit!important;
  }
}

//***************************
// STYLES
//***************************
// Make focus outline disappear on mouse actions
input:focus, button:focus, textarea:focus, select:focus, details:focus, [href]:focus, [tabindex]:not([tabindex="-1"]):focus, [contenteditable="true"]:focus {
  outline: none!important;
}
input:focus + label {
  outline: none!important;
}

// Focus style tab indexing for ADA only
input:focus-visible, button:focus-visible, textarea:focus-visible, select:focus-visible, details:focus-visible, [href]:focus-visible, [tabindex]:not([tabindex="-1"]):focus-visible, [contenteditable="true"]:focus-visible {
  outline: 1px dashed stencilColor("color-textLink--hover")!important;
  outline-offset: 1px!important;
}
input:focus-visible + label {
  outline: 1px dotted stencilColor("color-textLink--hover");
}

.optimizedCheckout-form-checklist-checkbox:checked ~ .form-label::before {
    border-color: inherit!important;
}

.layout-main {
    padding: 0;
    @media (min-width: $screen-large) {
        padding-right: 6rem;
    }
}
.layout-cart {
    padding: 0;
}

.checkoutHeader {
    border-width: 3px;
}
.checkoutHeader-content {
    padding: 1.5rem;
}
.checkoutHeader-content h1 {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 50px;
    margin: 0;

    .checkoutHeader-link {
        display: block;
        max-width: 200px;
        max-height: 100px;
    }

    strong {
        display: none;
        font-family: $ob-headings-font;

        @media (min-width: $screen-medium) {
            display: block;
        }
    }
}

.checkout-steps {
    padding: 0;
    @media (min-width: $screen-large) {
        padding-right: 6rem;
    }

    .stepHeader-counter.optimizedCheckout-step {
        display: flex!important;
        align-items: center;
        justify-content: center;
        width: 40px;
        height: 40px;
        border-radius: 100%;
        margin-right: 10px;
        background: stencilColor("section_indicator");
        transform: none!important;
        padding: 10px;
        font-weight: bold;

        svg {
            fill: stencilColor("section_indicator_icon");
            padding: 0;
        }

        &.stepHeader-counter--complete {
            background: stencilColor("section_indicator_complete");

            svg {
                fill: stencilColor("section_indicator_icon_complete");
            }
        }
    }
}

//***************************
// Custom Login Step
//***************************
.checkout-step--customer {
    .customerEmail-body {
        width: calc(100% - 122px);

        @media (min-width: $screen-small) {
            width: 58.3333333333%;
        }
    }

    .customerEmail-action {
        width: 122px;
        margin-top: 1.75rem;
        padding-left: 0.75rem;

        @media (min-width: $screen-small) {
            width: 41.6666666667%;
            margin-top: 1.8rem;
            padding-left: 10px;
        }
    }
}

.form-checklist.optimizedCheckout-form-checklist {
    background: none;
    border: none;

    .form-checklist-item.optimizedCheckout-form-checklist-item {
        margin: 0 0 5px;
        border: none;
        border-radius: $ob-border-radius;
        &:last-of-type {
            margin: 0;
        }

        .form-label.optimizedCheckout-form-label {
            display: flex;
            align-items: center;
            justify-content: space-between;
            width: 100%;
        }

        .shippingOptionLabel,
        .shippingOption {
            width: 100%;
        }

        .form-input,
        .form-select {
            background-color: stencilColor("checkout_alt_input_bg");
            color: stencilColor("checkout_alt_input_color");
            border-color: stencilColor("checkout_alt_input_border");
        }
    }
}

.cart.optimizedCheckout-orderSummary {
    border: none;
    border-radius: 0;
    box-shadow: none;
    background: none;

    a {
        color: stencilColor("color-textSecondary");
        text-decoration: underline;
    }

    .cart-header {
        background: stencilColor("content_inner_panel_bg");
        border-radius: $ob-border-radius $ob-border-radius 0 0;
    }
    .cart-section.optimizedCheckout-orderSummary-cartSection {
        &:not(:last-of-type) {
            background: stencilColor("content_inner_panel_bg");
        }
        &:last-of-type {
            background: stencilColor("content_inner_panel_secondary_bg");
            margin-top: 10px;
            border-radius: $ob-border-radius;
            border: none;

            [data-test="cart-total"] span {
                font-size: 14px;
                font-weight: bold;
            }
        }

        .product-column.product-figure {
            aspect-ratio: $ob-card-aspect-ratio;
            background: stencilColor("checkout_cart_image_background");
            padding: stencilNumber("product_card_image_padding");
            margin-right: 15px;
            border-radius: $ob-border-radius;
            overflow: hidden;

            img {
                mix-blend-mode: stencilString("product_image_blend_mode");
                width: 100%;
                height: 100%;
                object-fit: stencilString("product_card_image_fit");
            }
        }
        .product-title {
            font-size: 110%;
            font-weight: bold;
        }
    }
}

// VOGUE VARIANT
.ob-vogue-checkout {
    .cart.optimizedCheckout-orderSummary {
        .cart-header {
            border-radius: $ob-border-radius/2 $ob-border-radius/2 0 0;
        }
        .cart-section.optimizedCheckout-orderSummary-cartSection {
            &:nth-last-child(-n+2) {
                border-radius: 0 0 $ob-border-radius/2 $ob-border-radius/2;
            }
            &:last-child {
                border-radius: $ob-border-radius/3;
            }

            .product-column.product-figure {
                border-radius: $ob-border-radius/3;
            }
        }
    }
}

.cartDrawer.optimizedCheckout-orderSummary {
    margin: 0;
    background: stencilColor("content_inner_panel_bg");
    border: none;

    .cartDrawer-figure {
        aspect-ratio: $ob-card-aspect-ratio;
        background: stencilColor("checkout_cart_image_background");
        padding: 0;
        margin-right: 15px;
        border-radius: $ob-border-radius;
        overflow: hidden;
    }
}
.modalOverlay {
    background: rgba(0, 0, 0, 0.3);
}
.optimizedCheckout-cart-modal {
    background: stencilColor("optimizedCheckout-body-backgroundColor");
    box-shadow: 0 1px 4px rgba(stencilColor("optimizedCheckout-body-backgroundColor"), 0.4);
    .modal-header,
    .modal-body {
        background: none;
    }
    .product-column.product-figure {
        aspect-ratio: $ob-card-aspect-ratio;
        background: stencilColor("product_card_bg_color");
        padding: 0;
        margin: 0 15px 10px 0;
        border-radius: $ob-border-radius;
        display: flex;
        align-items: center;
        justify-content: center;
        overflow: hidden;

        img {
            mix-blend-mode: stencilString("product_image_blend_mode");
            width: 100%;
            height: 100%;
            object-fit: stencilString("product_card_image_fit");
        }
    }
}

//***************************
// Alert Boxes
//***************************
.alertBox {
  display: flex;
  height: auto;
  border-radius: $ob-border-radius;
  padding: 12px 15px;
  align-items: center;
  justify-content: flex-start;
  background: black;
  color: white;
  border: 2px solid black;

  .alertBox-icon {
    display: inline-flex;
    width: 20px;
    height: 20px;
    line-height: 14px;
    border-radius: 100%;
    align-items: center;
    justify-content: center;
    margin: 0 15px 0 0;
    padding: 2px 2px 0;
    color: inherit;

    svg {
        stroke: white;
        fill: white;
    }
  }
  .alertBox-message {
    width: calc(100% - 35px);
    color: inherit;

    p, span, strong {
      color: inherit;
    }
  }

  &--storeCredit {
    display: block;
  }
}

ob-custom/framework/ob-variables.scss:
//***************************
// FONTS
//***************************
$ob-body-font: stencilFontFamily('body-font');
$ob-body-font-weight: stencilFontWeight('body-font');

$ob-headings-font: stencilFontFamily('headings-font');
$ob-headings-font-weight: stencilFontWeight('headings-font');

$ob-pretitle-font: stencilFontFamily('pretitle-font');
$ob-pretitle-font-weight: stencilFontWeight('pretitle-font');

$ob-button-font: stencilFontFamily('button-font');
$ob-button-font-weight: stencilFontWeight('button-font');

//***************************
// FONT SIZES
//***************************
$ob-size-root: stencilNumber("fontSize-root");
$ob-size-button: stencilNumber("fontSize-button");
$ob-size-pretitle: stencilNumber("fontSize-pretitle");
$ob-size-product: stencilNumber("product_title_size");
$ob-size-h1: stencilNumber("fontSize-h1");
$ob-size-h2: stencilNumber("fontSize-h2");
$ob-size-h3: stencilNumber("fontSize-h3");
$ob-size-h4: stencilNumber("fontSize-h4");
$ob-size-h5: stencilNumber("fontSize-h5");
$ob-size-h6: stencilNumber("fontSize-h6");

//***************************
// COLORS
//***************************
$ob-text-primary: stencilColor("color-textBase");
$ob-text-secondary: stencilColor("color-textSecondary");

$ob-gradient: linear-gradient(90deg, stencilColor('color-primary') 0%, stencilColor('color-secondary') 100%);
$ob-gradient-inverted: linear-gradient(90deg, stencilColor('color-secondary') 0%, stencilColor('color-primary') 100%);
$ob-gradient-animated: linear-gradient(90deg, stencilColor('color-secondary'), stencilColor('color-primary'), stencilColor('color-secondary'));


//***************************
// WIDTHS / SIZES
//***************************
$cont-width: 1560px;
$row-width: 1560px;
$narrow-width: 1350px;
$base-page-width: 1150px;

$screen-xlarge:                 1441px;
$screen-large:                  1261px;
$screen-medium:                 801px;
$screen-tablet:                 768px;
$screen-small:                  551px;
$screen-tiny:                   1px;

//***************************
// OTHER
//***************************
$ob-border-radius: stencilNumber("border_radius");

$ob-card-fill-option: stencilString("product_card_image_fit");

$ob-card-aspect-option: stencilString("card_aspect_ratio");
$ob-card-aspect-ratio: 1/1.25;
@if $ob-card-aspect-option == 'landscape' {
    $ob-card-aspect-ratio: 1.25/1;
} @else if $ob-card-aspect-option == 'square' {
    $ob-card-aspect-ratio: 1/1;
}

$ob-subcat-aspect-option: stencilString("subcat_aspect_ratio");
$ob-subcat-aspect-ratio: 1/1.25;
@if $ob-subcat-aspect-option == 'landscape' {
    $ob-subcat-aspect-ratio: 1.25/1;
} @else if $ob-subcat-aspect-option == 'square' {
    $ob-subcat-aspect-ratio: 1/1;
}

ob-custom/global/ob-buttons.scss:
//***************************
//Button Styling
//***************************
.ob-btn, button,
.button, .button--primary,
.ob-cta-link,
.cart-actions .button,
.table-actions .button,
#consent-manager button,
.buttonLink a,
.form-minMaxRow button {
  padding: 0px 25px;
  height: 50px;
  letter-spacing: 0.2em;
  border-radius: $ob-border-radius;
  border: none;
  text-decoration: none;
  white-space: nowrap;
  transition: all ease-in-out .2s;
  display: inline-flex;
  width: auto;
  max-width: 100%;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  text-align: center;
  text-transform: uppercase;
  font-size:stencilNumber("fontSize-button") * .85;
  line-height: 110%;
  font-family: $ob-button-font;
  font-weight: $ob-button-font-weight;
  @media (min-width: $screen-medium) {
    height: 60px;
    font-size:stencilNumber("fontSize-button");
  }
  @media (min-width: $screen-large) {
    padding: 0 38px;
  }

  svg {
    transition: all ease-in-out .2s;
  }
}

.ob-btn {
  &-block {
    width: 100%!important;
  }
  &-border {
    background: stencilColor("button_bordered_background")!important;
    border: 4px solid stencilColor("button_bordered_border");
    color: stencilColor("button_bordered_text")!important;

    &:hover {
      background: stencilColor("button_bordered_background_hover")!important;
      border-color: stencilColor("button_bordered_border_hover");
      color: stencilColor("button_bordered_text_hover")!important;
      box-shadow: 0px 7px 28px -12px stencilColor("button_bordered_border");

      svg {
        stroke: stencilColor("button_bordered_text_hover");
        fill: stencilColor("button_bordered_text_hover");
      }
    }
  }
}

.form-minMaxRow button {
  background: stencilColor("button_bordered_background")!important;
  border: 4px solid stencilColor("button_bordered_border");
  color: stencilColor("button_bordered_text")!important;

  &:hover {
    background: stencilColor("button_bordered_background_hover")!important;
    border-color: stencilColor("button_bordered_border_hover");
    color: stencilColor("button_bordered_text_hover")!important;
    box-shadow: 0px 7px 28px -12px stencilColor("button_bordered_border");

    svg {
      stroke: stencilColor("button_bordered_text_hover");
      fill: stencilColor("button_bordered_text_hover");
    }
  }
}

.ob-btn--primary, .button--primary,
.modal .confirm.button,
#consent-manager button:not(:first-of-type),
.buttonLink a, .cart-modal-continue {
  background: stencilColor("button--primary-backgroundColor");
  color: stencilColor("button--primary-color")!important;

  &:hover {
    background: stencilColor("button--primary-backgroundColorHover");
    color: stencilColor("button--primary-colorHover")!important;
  }
}

#consent-manager button:first-of-type {
  background: stencilColor("button_bordered_background")!important;
  border: 4px solid stencilColor("button_bordered_border");
  color: stencilColor("button_bordered_text")!important;
  &:hover {
    background: stencilColor("button_bordered_background_hover")!important;
    border-color: stencilColor("button_bordered_border_hover");
    color: stencilColor("button_bordered_text_hover")!important;
    box-shadow: 0px 7px 28px -12px stencilColor("button_bordered_border");
    svg {
      stroke: stencilColor("button_bordered_text_hover");
      fill: stencilColor("button_bordered_text_hover");
    }
  }
}

button[disabled],
.button--primary[disabled],
.ob-btn[disabled] {
  background: stencilColor("button--disabled-backgroundColor")!important;
  border-color: stencilColor("button--disabled-backgroundColor")!important;
  color: stencilColor("button--disabled-color")!important;
  opacity: 0.9!important;

  &:hover {
    cursor: not-allowed;
  }
}

.ob-cta-link,
.modal .cancel.button {
  background: none!important;
  border-bottom: 2px solid stencilColor("button_cta_border");
  border-radius: 0;
  color: stencilColor("button_cta_text")!important;
  padding: 0;
  margin: 0 20px;
  height: 40px;

  svg {
    fill: none;
    display: flex;
    max-width: 28px;
    max-height: 28px;
    margin: 0 5px;
  }

  &.no-padding {
    padding: 0!important;
  }

  &:hover {
    border-color: stencilColor("button_cta_border_hover");
  }
}

.button--full-mobile {
  display: flex;
  width: 100%;
  @media (min-width: $screen-medium) {
    display: inline-flex;
    width: auto;
  }
}

// NIGHT VARIANT
[data-theme-variant="night"],
.ob-night-checkout {
  .ob-btn-border,
  .ob-btn--primary,
  .button--primary,
  .card-figcaption-button,
  .modal .confirm.button,
  #consent-manager button,
  .cart-modal-continue {
    &:not([disabled]) {
      &:hover {
        box-shadow: 0px 7px 28px -12px stencilColor("button--primary-backgroundColor");
      }
    }
  }
}

// VOGUE VARIANT
[data-theme-variant="vogue"],
.ob-vogue-checkout {
  .ob-btn, button,
  .button, .button--primary,
  .ob-cta-link,
  .cart-actions .button,
  .table-actions .button,
  #consent-manager button,
  .buttonLink a,
  .form-minMaxRow button {
    text-transform: capitalize!important;
    letter-spacing: 0.025em;
    padding: 0 20px;
    font-weight: 700;
    @media (min-width: $screen-medium) {
      height: 65px;
      padding: 0 30px;
    }
    @media (max-width: ($screen-medium - 1)) {
      font-size: 14px;
    }

    &-border {
      border: 3px solid stencilColor("button_bordered_border");
    }
  }

  #consent-manager button {
    height: 50px;
    padding: 0 25px;
  }

  .ob-btn--primary,
  .button--primary,
  .modal .confirm.button,
  #consent-manager button:not(:first-of-type),
  .cart-modal-continue {
    background: $ob-gradient;

    &:hover {
      background: $ob-gradient-inverted;
      box-shadow: none;
    }

    &[disabled] {
      background: $ob-gradient!important;
      opacity: 0.4!important;
      color: stencilColor("button--disabled-color")!important;
    }
  }
  .ob-btn-border,
  .form-minMaxRow button {
    &:hover {
      box-shadow: none;
    }
  }
}

ob-custom/global/ob-forms.scss:
.form-field {
  input:not([type="submit"]),
  textarea,
  select,
  input:not([type="submit"]):focus,
  textarea:focus,
  select:focus {
    background-color: stencilColor("input-bg-color");
    border-color: stencilColor("input-border-color");
    border-radius: $ob-border-radius!important;
    color: stencilColor("input-font-color");
    box-shadow: none;
    font-size: $ob-size-root * .75;
    @media (min-width: $screen-medium) {
      font-size: $ob-size-root * .825;
    }

    &::placeholder {
      color: $ob-text-secondary;
    }
  }

  label {
    color: stencilColor("form-label-font-color");
    font-weight: fontWeight("bold");
    font-size: $ob-size-root * .75;
    @media (min-width: $screen-medium) {
      font-size: $ob-size-root * .825;
    }

    small {
      color: inherit;
      float: none;
    }
  }
}

.estimator-form-input {
  input:not([type="submit"]),
  textarea,
  select,
  input:not([type="submit"]):focus,
  textarea:focus,
  select:focus {
    background-color: stencilColor("input-bg-color");
    border-color: stencilColor("input-border-color")!important;
    border-radius: $ob-border-radius!important;
    color: stencilColor("input-font-color");
    box-shadow: none;

    &::placeholder {
      color: $ob-text-secondary;
    }
  }
}

.form-radio + .form-label {
  display: flex;
  align-items: center;
  justify-content: flex-start;

  &:before,
  &:after {
    font-family: Arial, sans-serif;
  }

  &:before {
    border: 2px solid stencilColor("checkRadio-borderColor")!important;
    top: 0;
  }
  &:after {
    background: stencilColor("input-bg-color");
    transform: scale(0.8);
    top: 1px;
  }
}
.form-radio:checked + .form-label {
  &:after {
    background: stencilColor('color-activeForms');
  }
}

.form-checkbox + .form-label,
.navList-action--checkbox {
  display: flex;
  align-items: center;
  justify-content: flex-start;

  &:before {
    top: 0;
  }

  &:before {
    border: 2px solid stencilColor("checkbox-border-color")!important;
    background: stencilColor("checkbox-background-color");
    font-family: Arial, sans-serif;
  }
  &:after {
    background: none;
    color: stencilColor("checkbox-icon-color");
    top: 1.5px;
    right: 1px;
    font-family: Arial, sans-serif;
  }
}
.form-checkbox:checked + .form-label,
.navList-action--checkbox.is-selected {
  &:before {
    border-color: stencilColor("checkbox-active-color")!important;
    background: stencilColor("checkbox-active-color");
  }
  &:after {
    color: stencilColor("checkbox-icon-color")!important;
    content: '\2713'!important;
    font-weight: 700;
  }
}

.navList-action--checkbox {
  font-size: $ob-size-root * .75;
  padding-top: 0;
  padding-bottom: 5px;
  @media (min-width: $screen-medium) {
    font-size: $ob-size-root * .825;
  }
}

.form-field select {
  appearance: none;
  -webkit-appearance: none;
  background-image: $select-backgroundImage;
  background-position: right 15px center;
  padding: $select-padding;
  background-repeat: no-repeat;
}

input::placeholder {
  color: stencilColor("input-placeholder-color");
}

.form-increment {
  input {
    border-radius: $ob-border-radius;
  }
}

.dropdown-chevron {
  display: none!important;
}

// VOGUE VARIANT
[data-theme-variant="vogue"],
.ob-vogue-checkout {
  .form-field {
    input:not([type="submit"]),
    textarea,
    select {
      min-height: 50px;
    }
    input:not([type="submit"]) {
      padding: calc(0.75rem + 2px) 1rem 0.75rem;
    }
  }
  textarea {
    border-radius: $ob-border-radius / 2!important;
  }
  .form-checkbox + .form-label {
    &:after {
      top: 2px;
    }
  }
}
